def gen(rng):
    LIM = 10**9

    def fmt(a, b, c, d):
        return f'{a} {b} {c} {d}'

    def walk(a, b, runs, maxrun):
        x, y = a, b
        for _ in range(runs):
            side = rng.randint(0, 1)
            for _ in range(rng.randint(1, maxrun)):
                nx, ny = (x + y, y) if side == 0 else (x, x + y)
                if nx > LIM or ny > LIM:
                    return x, y
                x, y = nx, ny
        return x, y

    tests = [
        fmt(2, 3, 5, 13), fmt(3, 4, 10, 4), fmt(6, 6, 6, 6), fmt(1, 1, 1, 1),
        fmt(1, 1, 2, 2), fmt(1, 1, 1, LIM), fmt(1, 1, LIM, 1), fmt(1, 1, LIM, LIM),
        fmt(1, 1, LIM - 1, LIM), fmt(5, 1, LIM, 1), fmt(5, 1, LIM - 1, 1),
        fmt(2, 2, LIM, LIM), fmt(7, 4, 3, 4),
    ]
    for _ in range(60):
        a, b = rng.randint(1, 6), rng.randint(1, 6)
        mode = rng.randint(0, 2)
        if mode == 0:
            c, d = rng.randint(1, 40), rng.randint(1, 40)
        else:
            c, d = walk(a, b, rng.randint(0, 6), 4)
            if mode == 2:
                c, d = c + rng.randint(0, 2), d + rng.randint(0, 2)
            if c > 60 or d > 60:
                c, d = rng.randint(1, 60), rng.randint(1, 60)
        tests.append(fmt(a, b, c, d))
    for _ in range(12):
        a, b = rng.randint(1, 1000), rng.randint(1, 1000)
        c, d = walk(a, b, rng.randint(1, 60), 10**6)
        tests.append(fmt(a, b, c, d))
        tests.append(fmt(a, b, c, min(LIM, d + rng.randint(1, 3))))
    return tests

